mapper.update:
UPDATE users
SET failed_login_count = failed_login_count + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND locked_at IS NULL
  AND deleted_at IS NULL

UPDATE users
SET password_hash = #{passwordHash},
    failed_login_count = CASE WHEN locked_at IS NULL THEN 0 ELSE failed_login_count END,
    session_valid_after = #{sessionValidAfter},
    updated_at = #{now},
    updated_by = #{id}
WHERE id = #{id}
  AND password_hash = #{expectedHash}
  AND deleted_at IS NULL
